// Extract jobId from webhook data
const webhookData = $input.all()[0].json;
let jobId = null;

// Debug: Log the webhook data structure
console.log('Webhook data structure:', Object.keys(webhookData));
console.log('Query object:', webhookData.query);
console.log('Params object:', webhookData.params);

// Try multiple ways to get the jobId
if (webhookData.query && webhookData.query.jobId) {
  jobId = webhookData.query.jobId;
  console.log('Found jobId in query:', jobId);
} else if (webhookData.params && webhookData.params.jobId) {
  jobId = webhookData.params.jobId;
  console.log('Found jobId in params:', jobId);
} else {
  // Try to parse from the webhookUrl
  const webhookUrl = webhookData.webhookUrl || '';
  console.log('Webhook URL:', webhookUrl);

  if (webhookUrl.includes('?')) {
    const urlParams = new URLSearchParams(webhookUrl.split('?')[1]);
    jobId = urlParams.get('jobId');
    console.log('Extracted jobId from URL:', jobId);
  }
}

// Validate jobId
if (!jobId || jobId.trim() === '') {
  console.log('No valid jobId found');
  return [{
    json: {
      error: 'missing_job_id',
      message: 'Job ID is required as a query parameter: ?jobId=your-job-id',
      receivedData: {
        query: webhookData.query,
        params: webhookData.params,
        url: webhookData.webhookUrl
      }
    }
  }];
}

console.log('Final jobId:', jobId);

return [{
  json: {
    ...webhookData,
    jobId: jobId.trim()
  }
}];

// Process the job status and format response
const inputItems = $input.all();
const requestedJobId = $('Extract Job ID').item.json.jobId;

console.log('Input items count:', inputItems.length);
console.log('Requested Job ID:', requestedJobId);

// Check if we found a job
if (!inputItems || inputItems.length === 0 || !inputItems[0].json || !inputItems[0].json['Job ID']) {
  console.log('Job not found in Google Sheets');
  return [{
    json: {
      status: 'not_found',
      message: 'Job not found in our records. Please check your Job ID.',
      jobId: requestedJobId,
      progress: 0,
      error: true
    }
  }];
}

const jobData = inputItems[0].json;
console.log('Found job data:', Object.keys(jobData));

// Determine status details
let statusDetails = {
  jobId: jobData['Job ID'],
  status: jobData.Status || 'unknown',
  fullName: jobData['Full Name'],
  email: jobData['Your Email'],
  request: jobData['Your Request'],
  aspectRatio: jobData['Aspect Ratio'],
  createdAt: jobData['Created At'],
  videoUrl: jobData['Final Video URL'] || null,
  errorMessage: jobData['Eror message'] || null
};

console.log('Job status:', statusDetails.status);

// Set progress and message based on status
switch(statusDetails.status.toLowerCase()) {
  case 'pending':
    statusDetails.progress = 25;
    statusDetails.message = 'Your request is in the queue and will be processed shortly';
    break;

  case 'processing':
    statusDetails.progress = 75;
    statusDetails.message = 'Your video is being generated with AI magic!';
    break;

  case 'complete':
    statusDetails.progress = 100;
    statusDetails.message = 'Your video is ready! Check your email for the download link.';
    break;

  case 'error':
    statusDetails.progress = 0;
    statusDetails.message = statusDetails.errorMessage || 'An error occurred during processing';
    statusDetails.error = true;
    break;

  default:
    statusDetails.progress = 0;
    statusDetails.message = `Status: ${statusDetails.status}`;
}

return [{
  json: statusDetails
}];
